import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/configuration.md","filePath":"zh/guide/configuration.md","lastUpdated":1786971590000}'),o={name:"zh/guide/configuration.md"};function s(l,t,r,n,c,h){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h1><p>NeoFlux 使用 gflags 进行运行时配置，所有参数均为可选。</p><h2 id="命令行参数" tabindex="-1">命令行参数 <a class="header-anchor" href="#命令行参数" aria-label="Permalink to &quot;命令行参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>--target_fps</code></td><td>int</td><td><code>60</code></td><td>应用事件循环与渲染的目标帧率</td></tr><tr><td><code>--render_queue_capacity</code></td><td>int</td><td><code>2048</code></td><td>SPSC 无锁环形队列容量，自动向上取整为 2 的幂</td></tr><tr><td><code>--verbose_logging</code></td><td>bool</td><td><code>false</code></td><td>启用详细 VLOG(1) 输出并将日志镜像到 stderr</td></tr><tr><td><code>--logtostderr</code></td><td>bool</td><td><code>false</code></td><td>将日志输出到 stderr 而非日志文件</td></tr><tr><td><code>--log_dir</code></td><td>string</td><td><code>./logs</code></td><td>日志文件存放目录，不存在时自动创建</td></tr><tr><td><code>--render_backend</code></td><td>string</td><td><code>vulkan</code></td><td>渲染后端：<code>vulkan</code>、<code>gl</code>、<code>cpu</code></td></tr></tbody></table><h2 id="日志配置" tabindex="-1">日志配置 <a class="header-anchor" href="#日志配置" aria-label="Permalink to &quot;日志配置&quot;">​</a></h2><p>默认日志输出到 <code>./logs/</code> 文件，Windows 下不显示控制台窗口（<code>CMAKE_WIN32_EXECUTABLE</code>）。</p><p>调试时使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/hello_neoflux</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --logtostderr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose_logging</span></span></code></pre></div><h2 id="渲染后端" tabindex="-1">渲染后端 <a class="header-anchor" href="#渲染后端" aria-label="Permalink to &quot;渲染后端&quot;">​</a></h2><p><code>--render_backend</code> 支持以下选项：</p><ul><li><code>vulkan</code>（默认）：Vulkan 渲染，当前回退到 OpenGL</li><li><code>gl</code>：OpenGL 渲染</li><li><code>cpu</code>：软件光栅化，当前回退到 OpenGL</li></ul><p>未实现的后端会输出警告并回退到 OpenGL。</p><h2 id="cmake-选项" tabindex="-1">CMake 选项 <a class="header-anchor" href="#cmake-选项" aria-label="Permalink to &quot;CMake 选项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>选项</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>NEOFLUX_BUILD_TESTS</code></td><td><code>OFF</code></td><td>编译单元测试</td></tr></tbody></table><p>启用测试：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DNEOFLUX_BUILD_TESTS=ON</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./cross-platform">跨平台</a></li><li><a href="./testing">测试</a></li></ul>',18)])])}const u=e(o,[["render",s]]);export{k as __pageData,u as default};
